mapper.select:
SELECT c.id AS customer_id, c.phone AS phone, c.email AS email, NULL AS kakao_user_key, NVL(ccc.kakao_consent, 0) AS kakao_consent, NVL(ccc.email_consent, 0) AS email_consent, NVL(ccc.sms_consent, 0) AS sms_consent FROM customer c LEFT JOIN ( SELECT sub_ccc.customer_id, MAX(CASE WHEN sub_ch.channel_type IN ('KAKAO', 'KAKAO_ALIM') THEN sub_ccc.is_consented ELSE 0 END) AS kakao_consent, MAX(CASE WHEN sub_ch.channel_type = 'EMAIL' THEN sub_ccc.is_consented ELSE 0 END) AS email_consent, MAX(CASE WHEN sub_ch.channel_type IN ('SMS', 'LMS') THEN sub_ccc.is_consented ELSE 0 END) AS sms_consent FROM customer_channel_consent sub_ccc JOIN channel sub_ch ON sub_ccc.channel_id = sub_ch.id WHERE NVL(sub_ccc.is_deleted, 0) = 0 AND NVL(sub_ch.is_deleted, 0) = 0 GROUP BY sub_ccc.customer_id ) ccc ON c.id = ccc.customer_id WHERE NVL(c.is_deleted, 0) = 0 AND NVL(c.is_ad_blocked, 0) = 0 AND c.id IN
#{customerId}
ORDER BY c.id ASC

mapper.insert:
INSERT INTO send_history ( template_id, user_id, title, content, purpose, status, total_target_count, success_count, fail_count, estimated_cost, estimated_saving, actual_cost, scheduled_at,
) VALUES ( #{templateId, jdbcType=BIGINT}, #{userId, jdbcType=BIGINT}, #{title, jdbcType=VARCHAR}, #{content, jdbcType=VARCHAR}, #{purpose, jdbcType=VARCHAR}, #{status, jdbcType=VARCHAR}, #{totalTargetCount, jdbcType=INTEGER}, #{successCount, jdbcType=INTEGER}, #{failCount, jdbcType=INTEGER}, #{estimatedCost, jdbcType=DECIMAL}, #{estimatedSaving, jdbcType=DECIMAL}, #{actualCost, jdbcType=DECIMAL}, #{scheduledAt, jdbcType=TIMESTAMP},
)

INSERT INTO send_history_routing ( send_history_id, channel_id, priority_order,
) VALUES ( #{sendHistoryId, jdbcType=BIGINT}, #{channelId, jdbcType=BIGINT}, #{priorityOrder, jdbcType=INTEGER},
)

INSERT INTO send_target ( send_history_id, customer_id, final_channel_id, status, cost, user_uuid,
) VALUES ( #{sendHistoryId, jdbcType=BIGINT}, #{customerId, jdbcType=BIGINT}, #{finalChannelId, jdbcType=BIGINT}, #{status, jdbcType=VARCHAR}, #{cost, jdbcType=DECIMAL}, #{userUuid, jdbcType=VARCHAR},
)
